Let's write down what `src/storage/node-fs.ts` looks like:

```ts
import { stat, readFile } from "node:fs/promises";
import { resolve } from "pathe";
import type { Storage } from "../types";
import { createError } from "../utils";

export interface NodeFSStorageOptions {
  dir?: string;
  maxAge?: number;
}

export function ipxFSStorage(_options: NodeFSStorageOptions = {}): Storage {
  const dir = resolve(_options.dir || ".");

  const _resolvePath = (id: string) => {
    const filePath = resolve(dir, id);
    if (!filePath.startsWith(dir.endsWith("/") ? dir : dir + "/")) {
      throw createError({
        statusCode: 403,
        statusText: `Forbidden path: ${id}`,
      });
    }
    return filePath;
  };

  return {
    name: "ipx:node-fs",
    async getMeta(id) {
      const filePath = _resolvePath(id);
      const stats = await stat(filePath);
      return {
        mtime: stats.mtime,
        size: stats.size,
      };
    },
    async getData(id) {
      const filePath = _resolvePath(id);
      return readFile(filePath);
    },
  };
}
```

