/**
 * Parses structured e-mail addresses from an address header string
 *
 * @param {String} str Address header string
 * @return {Array} An array of address objects
 */
function addressparser(str, options) {
    options = options || {};

    let tokenizer = new Tokenizer(str);
    let tokens = tokenizer.tokenize();

    let addresses = [];
    let address = {
        name: '',
        address: ''
    };
    let state = 'text';

    tokens.forEach(token => {
        if (token.type === 'operator') {
            switch (token.value) {
                case '<':
                    state = 'address';
                    break;
                case '>':
                    state = 'text';
                    break;
                case ',':
                case ';':
                    if (address.name || address.address) {
                        addresses.push(address);
                    }
                    address = {
                        name: '',
                        address: ''
                    };
                    state = 'text';
                    break;
                default:
                    if (state === 'address') {
                        address.address += token.value;
                    } else {
                        address.name += token.value;
                    }
            }
        } else {
            if (state === 'address') {
                address.address += token.value;
            } else {
                address.name += token.value;
            }
        }
    });

    if (address.name || address.address) {
        addresses.push(address);
    }

    addresses.forEach(address => {
        address.name = (address.name || '').trim();
        address.address = (address.address || '').trim();

        if (!address.address && address.name) {
            if (address.name.match(/@/)) {
                let match = address.name.match(/(^|[\s,])([^@\s]+@[^@\s]+)($|[\s,])/);
                if (match) {
                    address.address = match[2];
                    address.name = address.name.replace(match[2], '').trim();
                } else {
                    address.address = address.name;
                    address.name = '';
                }
            }
        }
    });

    return addresses;
}

module.exports = addressparser;
